#!/usr/bin/env node
/**
 * Re-record the offline test fixtures from the live Open-Meteo APIs.
 *
 *   node scripts/record-fixtures.mjs
 *
 * Every response is written verbatim (pretty-printed) into fixtures/, and
 * fixtures/manifest.json records the exact URL and the UTC timestamp of the fetch.
 * Fixtures are deliberately NOT regenerated by the test run: a shape change must
 * show up as a reviewable diff.
 *
 * Test point: Appalachian Trail ridge, Great Smoky Mountains, 35.60 N 83.43 W,
 * real trail elevation ~1800 m (Open-Meteo's own 90 m DEM says 1446 m there).
 */
import { writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const FIXTURES = join(HERE, '..', 'fixtures');

const LAT = 35.6;
const LON = -83.43;
const ELEV = 1800;
const HOURLY =
  'temperature_2m,relative_humidity_2m,wind_speed_10m,cloud_cover,precipitation,precipitation_probability,shortwave_radiation';
const ARCHIVE_HOURLY =
  'temperature_2m,relative_humidity_2m,wind_speed_10m,cloud_cover,precipitation,shortwave_radiation';

/** @type {{file: string, url: string, note: string}[]} */
const JOBS = [
  {
    file: 'geocoding-gatlinburg.json',
    url: 'https://geocoding-api.open-meteo.com/v1/search?name=Gatlinburg&count=5&language=en&format=json',
    note: 'Ranked geocoding candidates; used for the "Gatlinburg, Tennessee, United States" label test.',
  },
  {
    file: 'geocoding-empty.json',
    url: 'https://geocoding-api.open-meteo.com/v1/search?name=zzzzqqqxyz&count=5&language=en&format=json',
    note: 'No-match response. NOTE: the API omits the `results` key entirely rather than returning [].',
  },
  {
    file: 'elevation-smokies-batch.json',
    url: `https://api.open-meteo.com/v1/elevation?latitude=35.6,35.71453,36.1&longitude=-83.43,-83.51189,-83.8`,
    note: 'Batched 90 m DEM lookup (AT ridge, Gatlinburg, a valley point). Proves comma-batching works.',
  },
  {
    file: 'forecast-smokies-no-elevation.json',
    url: `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}&hourly=${HOURLY}&daily=sunrise,sunset&forecast_days=16&timezone=auto&wind_speed_unit=ms`,
    note: 'Forecast WITHOUT elevation=. Open-Meteo reports elevation 1446 m (its own DEM) and lapses to that.',
  },
  {
    file: 'forecast-smokies-elevation-1800.json',
    url: `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}&hourly=${HOURLY}&daily=sunrise,sunset&forecast_days=16&timezone=auto&wind_speed_unit=ms&elevation=${ELEV}`,
    note: 'Same request WITH elevation=1800. Pair with the previous fixture to measure the lapse correction.',
  },
  {
    file: 'forecast-smokies-short.json',
    url: `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}&hourly=${HOURLY}&daily=sunrise,sunset&forecast_days=3&timezone=auto&wind_speed_unit=ms&elevation=${ELEV}`,
    note: 'Small 3-day forecast used by the fast sampler tests.',
  },
  {
    file: 'error-bad-latitude.json',
    url: 'https://api.open-meteo.com/v1/forecast?latitude=999&longitude=-83.43&hourly=temperature_2m',
    note: 'Open-Meteo error envelope: HTTP 400 with {"error":true,"reason":"..."}.',
  },
];

// 20 years of the same calendar window around 20 November, one request per year.
const CLIMO_YEARS = [];
for (let y = 2006; y <= 2025; y++) {
  CLIMO_YEARS.push(y);
  JOBS.push({
    file: `archive/archive-smokies-${y}.json`,
    url:
      `https://archive-api.open-meteo.com/v1/archive?latitude=${LAT}&longitude=${LON}` +
      `&start_date=${y}-11-17&end_date=${y}-11-23&hourly=${ARCHIVE_HOURLY}` +
      `&daily=sunrise,sunset&timezone=auto&wind_speed_unit=ms&elevation=${ELEV}`,
    note: `ERA5 reanalysis, 20 Nov ±3 days, ${y}. One of ${20} years pooled into the climatology fallback.`,
  });
}

async function main() {
  const manifest = {
    recordedAtUtc: new Date().toISOString(),
    testPoint: { latitude: LAT, longitude: LON, assumedTrailElevationMetres: ELEV },
    attribution: 'Weather data by Open-Meteo.com, CC BY 4.0.',
    files: {},
  };

  for (const job of JOBS) {
    const res = await fetch(job.url);
    const text = await res.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      throw new Error(`Non-JSON response for ${job.url}: ${text.slice(0, 200)}`);
    }
    const out = join(FIXTURES, job.file);
    await mkdir(dirname(out), { recursive: true });
    await writeFile(out, JSON.stringify(body, null, 2) + '\n');
    manifest.files[job.file] = {
      url: job.url,
      httpStatus: res.status,
      fetchedAtUtc: new Date().toISOString(),
      note: job.note,
    };
    console.log(`${res.status}  ${job.file}`);
    await new Promise((r) => setTimeout(r, 120)); // stay well inside 600 req/min
  }

  manifest.climatologyYears = CLIMO_YEARS;
  await writeFile(join(FIXTURES, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
  console.log(`\nwrote fixtures/manifest.json (${Object.keys(manifest.files).length} files)`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
